  "revision_action": "keep",
  "supportive_card_ids": ["C15","C07","C11","C02","C12","C47","C44","C62"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C15","C07","C11","C02","C12","C47","C44","C62"],
  "claims": [
    {
      "claim": "Direct L1 absolute/systemic F measurements for ionized or acidic reference molecules are at or above the 20% threshold: neotame at least 34.3% in fasted healthy volunteers, 6-MNA 35-38% in healthy subjects, and tolfenamic acid 91-100% in cirrhosis patients.",
      "card_ids": ["C15","C07","C11","C02","C12"]
    },
    {
      "claim": "L4 human fraction-absorbed records show carboxylic acid-containing molecules are well absorbed despite ionization: naproxen 98-100%, ketoprofen 100%, fenoprofen readily absorbed, and aspirin complete from solution.",
      "card_ids": ["C47","C51","C53","C44","C46","C48","C49","C45","C52"]
    },
    {
      "claim": "L5 gut-wall efflux records show acidic/zwitterionic reference molecules have efflux ratios near 1 and high bidirectional permeability, with no affirmative efflux or intestinal-metabolism liability for the query.",
      "card_ids": ["C62","C58","C65","C61","C56","C57","C60","C54","C55","C63","C64"]
    },
    {
      "claim": "L6 hepatic-clearance records are for reference molecules (CYP2C9 substrate identifications, one HLM half-life, one glucuronidation CLint) and do not provide query-specific low-F evidence; none establishes F <20% for the query.",
      "card_ids": ["C66","C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C66","C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule is available in the supplied records.",
    "No query-specific hepatic clearance or metabolic-stability data are available; L6 records are for reference molecules and are not independent gold votes.",
    "The query's estimated logD (-2.72) is much lower than most reference acids (naproxen, ketoprofen, fenoprofen, 6-MNA), limiting transferability of their high fraction-absorbed and F results.",
    "No query-specific permeability, efflux, or intestinal-metabolism data are available; L4/L5 records are for reference molecules.",
    "Active transport or paracellular absorption for the query cannot be ruled out without experimental data."
  ],
  "decision_summary": "L6 hepatic-clearance records do not provide query-specific low-F evidence; they identify CYP2C9 metabolism for reference acids and one HLM half-life/one glucuronidation CLint for other molecules, but none establishes F <20% for the query. Direct L1 F values for ionized/acidic analogs (neotame ≥34.3%, 6-MNA 35-38%, tolfenamic acid 91-100%) and L4/L5 absorption/efflux records support F ≥20%, so the high prediction is kept with moderate confidence."
}

